/* Shared optional clarity message block. Page colours remain local tokens. */
body .ark-clarity-study .melts-ritual67[data-section-block136=message]{display:flex;align-items:center;justify-content:center;gap:28px;width:fit-content;max-width:100%;margin:30px auto 34px;padding:20px 32px;border:2px solid #1a1a1f;border-radius:20px;background:var(--clarity-message-paper,var(--pale,#fffef7));color:#1a1a1f;box-shadow:5px 6px 0 #1a1a1f;transform:rotate(-1deg)}
body .ark-clarity-study .melts-ritual67[data-section-block136=message]>svg,body .ark-clarity-study .melts-ritual67[data-section-block136=message]>img{width:150px;height:auto;flex:0 0 150px;object-fit:contain}
body .ark-clarity-study .melts-ritual67[data-section-block136=message] h3{display:flex;flex-direction:column;gap:3px;margin:0;padding:0;border:0;font:800 clamp(30px,3.1vw,44px)/1.1 Oswald,sans-serif;letter-spacing:-.02em;text-align:left;color:#1a1a1f}
body .ark-clarity-study .melts-ritual67[data-section-block136=message] h3>span{display:block;max-width:100%}
body .ark-clarity-study .melts-ritual67[data-section-block136=message] h3>span:last-child{color:var(--brand,#084254)}
/* Desktop is deliberately constrained; only the mobile rail reaches the edge. */
body [data-review-slider128]>:is(.ark-review-inner,.home-inner67){width:min(1200px,calc(100% - 60px));max-width:1200px;padding:0;margin-inline:auto}
body [data-review-slider128] :is(.ark-review-heading,.home-heading67){margin-inline:0}
body [data-review-slider128] .ark-review-track[data-review-rail128]{padding-left:0!important;scroll-padding-inline:0}
.review-card122[hidden]{display:none!important}
.reviews-pagination136{text-align:center;margin:28px auto 0}
.reviews-pagination136 button{font:600 15px/1.2 Inter,sans-serif;padding:14px 32px;min-height:46px;border:1px solid #1a1a1f;border-radius:7px;background:#fff;color:#1a1a1f;cursor:pointer}
.reviews-pagination136 button:hover{background:#f4f5f1}
.reviews-pagination136 button:focus-visible{outline:3px solid var(--accent,#b4df65);outline-offset:4px}
.reviews-pagination136 p{font:400 13px/1.5 Inter,sans-serif;color:#52635d;margin:12px 0}
/* Neutral, transparent comparison objects, unchanged product-specific facts. */
.comparison130 .comparison130__objects img[data-comparison-object="coffee"],.comparison130 .comparison130__objects img[data-comparison-object="can"]{height:70px;max-height:70px;object-fit:contain;background:transparent;mix-blend-mode:normal}
.comparison130 .comparison130__objects img[data-comparison-object="other-mouth"],.comparison130 .comparison130__objects img[data-comparison-object="other-nasal"]{height:65px;max-width:90%}
@media(max-width:767px){
 body .ark-clarity-study .melts-ritual67[data-section-block136=message]{gap:12px;padding:18px 16px;margin:26px auto 30px;border-radius:16px;box-shadow:4px 5px 0 #1a1a1f}
 body .ark-clarity-study .melts-ritual67[data-section-block136=message]>svg,body .ark-clarity-study .melts-ritual67[data-section-block136=message]>img{width:92px;flex-basis:92px}
 body .ark-clarity-study .melts-ritual67[data-section-block136=message] h3{font-size:clamp(25px,6.3vw,34px)}
 body [data-review-slider128]>:is(.ark-review-inner,.home-inner67){width:100%;max-width:none}
 body [data-review-slider128] :is(.ark-review-heading,.home-heading67){margin-inline:20px}
 body [data-review-slider128] .ark-review-track[data-review-rail128]{grid-auto-columns:86%!important;padding-left:20px!important;padding-right:20px!important;scroll-padding-inline:20px}
 .comparison130 .comparison130__objects img[data-comparison-object="coffee"],.comparison130 .comparison130__objects img[data-comparison-object="can"]{height:46px;max-height:46px}
 .comparison130 .comparison130__objects img[data-comparison-object^="other-"]{height:44px}
}
@media(max-width:359px){body .ark-clarity-study .melts-ritual67[data-section-block136=message]{flex-direction:column;gap:4px;transform:none}body .ark-clarity-study .melts-ritual67[data-section-block136=message]>svg{width:100px;flex-basis:auto}body .ark-clarity-study .melts-ritual67[data-section-block136=message] h3{text-align:center;font-size:29px}}
.ark-large-text64 body .ark-clarity-study .melts-ritual67[data-section-block136=message]{flex-direction:column;transform:none}

/* Static captured reviews only. No API/network, duplicate records or automatic loads. */
(()=>{'use strict';
 document.querySelectorAll('.clean-reviews122').forEach(section=>{
  if(section.dataset.batches136)return;
  const cards=[...section.querySelectorAll('.review-card122')];if(!cards.length)return;
  section.dataset.batches136='true';const step=12;let shown=Math.min(step,cards.length);
  const controls=document.createElement('div');controls.className='reviews-pagination136';
  const button=document.createElement('button');button.type='button';button.textContent='Load more';
  const status=document.createElement('p');status.setAttribute('role','status');status.setAttribute('aria-live','polite');status.setAttribute('aria-atomic','true');
  controls.append(button,status);const inner=section.querySelector('.reviews-inner122');
  const oldStatus=[...inner.children].find(n=>n.matches('p.reviews-context122'));
  if(oldStatus)oldStatus.hidden=true;
  const link=inner.querySelector('.reviews-more122');inner.insertBefore(controls,link||null);
  function paint(){cards.forEach((card,i)=>{card.hidden=i>=shown;const image=card.querySelector('img');if(image)image.loading='lazy'});button.hidden=shown>=cards.length;status.textContent=shown>=cards.length?`All ${cards.length} available preview reviews shown.`:`Showing ${shown} of ${cards.length} available reviews.`;}
  button.addEventListener('click',()=>{const first=cards[shown];shown=Math.min(shown+step,cards.length);paint();if(first){first.tabIndex=-1;first.focus({preventScroll:true})}});
  paint();
 });
})();
